package com.madhukar.upisplitter.util;
import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class PaymentSplitterTest{@Test void split4500(){assertEquals(List.of(new BigDecimal("1999"),new BigDecimal("1999"),new BigDecimal("502")),PaymentSplitter.split(new BigDecimal("4500"),new BigDecimal("1999")));}@Test void splitEqual(){assertEquals(List.of(new BigDecimal("1999")),PaymentSplitter.split(new BigDecimal("1999"),new BigDecimal("1999")));}@Test void split2000(){assertEquals(List.of(new BigDecimal("1999"),new BigDecimal("1")),PaymentSplitter.split(new BigDecimal("2000"),new BigDecimal("1999")));}@Test void splitSmall(){assertEquals(List.of(new BigDecimal("500")),PaymentSplitter.split(new BigDecimal("500"),new BigDecimal("1999")));}@Test void invalid(){assertThrows(IllegalArgumentException.class,()->PaymentSplitter.split(new BigDecimal("0"),new BigDecimal("10")));}}
